from flask import Flask, render_template, request, jsonifyimport osimport smtplibfrom email.mime.text import MIMETextimport requestsapp = Flask(__name__)@app.route("/")def index():    return render_template("index.html")@app.route("/test-json")def test_json():    return jsonify({"status": "ok", "message": "Flask fonctionne bien"})@app.route('/contact-sponsor', methods=['POST'])def contact_sponsor():    choix = request.form.get('choix')    email = request.form.get('email')    if not choix or not email:        return jsonify({            "status": "error",            "message": "Données manquantes"        }), 400    api_key = os.environ.get("RESEND_API_KEY")    email_to = os.environ.get("EMAIL_TO")    payload = {        "from": "La Syzygie <onboarding@resend.dev>",        "to": [email_to],        "subject": "Nouveau contact sponsor",        "html": f"""        <h2>Nouvelle demande sponsor</h2>        <p><strong>Choix :</strong> {choix}</p>        <p><strong>Email :</strong> {email}</p>        """    }    try:        response = requests.post(            "https://api.resend.com/emails",            headers={                "Authorization": f"Bearer {api_key}",                "Content-Type": "application/json"            },            json=payload,            timeout=10        )        print(response.text)        return jsonify({"status": "ok"})    except Exception as e:        print(e)        return jsonify({            "status": "error",            "message": str(e)        }), 500@app.route("/equipage")def equipage():    return render_template("equipe.html")@app.route("/sponsor")def sponsor():    return render_template("sponsor.html")@app.route("/concept")def concept():    return render_template("concept.html")@app.route("/pourquoi")def pourquoi():    return render_template("pourquoi.html")@app.route("/financer")def financer():    return render_template("financer.html")if __name__ == "__main__":    app.run(debug=True)    